mapper.select:
SELECT t.id, t.name, t.teacher_no AS teacherNo, t.college_id AS collegeId FROM t_teacher t LEFT JOIN t_user u ON u.ref_id = t.id AND u.user_type = 'TEACHER' LEFT JOIN t_user_role ur ON ur.user_id = u.id LEFT JOIN t_role r ON r.id = ur.role_id
u.status = 1
AND r.role_code = #{roleCode}
AND t.college_id = #{collegeId}
GROUP BY t.id, t.name, t.teacher_no, t.college_id ORDER BY t.id
